<div class="card"><h3>Alertas preventivas</h3><div class="table-wrap"><table><thead><tr><th>Caso</th><th>Paciente</th><th>Sustancia</th><th>Nivel</th><th>Mensaje</th><th>Estado</th><th>Acción</th></tr></thead><tbody><?php foreach($alertas as $a): ?><tr><td><a href="<?= e(url('caso','show',['id'=>(int)$a['caso_id']])) ?>"><?= e($a['codigo']) ?></a></td><td><?= e($a['nombres']) ?></td><td><?= e($a['sustancia']) ?></td><td><span class="pill <?= level_class($a['nivel']) ?>"><?= e($a['nivel']) ?></span></td><td><?= e($a['mensaje']) ?></td><td><?= e($a['estado']) ?></td><td><?php if(has_role(['ADMINISTRADOR','ESPECIALISTA','AUTORIDAD'])): ?><form method="post" action="<?= e(url('alerta','update')) ?>" class="inline-form"><?= csrf_field() ?><input type="hidden" name="alerta_id" value="<?= (int)$a['id'] ?>"><select name="estado"><option>PENDIENTE</option><option>REVISADA</option><option>CERRADA</option></select><button class="btn small">Actualizar</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></div>
